// #e94412 (6a993d709f3da75a35e94412) — экран завершения S-17 и подтверждение для кандидата (F-30). Кейсы CALL-027…CALL-030.
// БЕЗ звонков: по ГОТОВЫМ попыткам 21.10 ссылка кандидата открывается заново (только чтение).
//  - успех (QA-C4-2110-D2 08c67252, QA-DIAG-2110 0cee9d02): «הסימולציה הושלמה», имя бизнеса в тексте, без балла/отчёта/отзыва,
//    повторное открытие и reload — только S-17, старта нет;
//  - сбой: кандидат, у которого ТЕКУЩАЯ официальная попытка technical_failure и ссылка не отменена/не истекла —
//    «השיחה לא הושלמה» + плашка «החלק של השיחה שהוקלט עד הניתוק נשמר.» + «פנייה לגורם אנושי».
//    QA-C6-2110-D2 после проверки 21.10 сброшен (ссылка a6e6cb7a отменена, вторая попытка completed) — для него экран сбоя
//    больше не открывается; без подходящего кандидата тест падает с пометкой «нет данных» (ОКРУЖЕНИЕ, не баг).
//  - список кандидатов business: «הושלמה» / «תקלה טכנית».
// Страховка blockCallStarts: старт попытки и голосовой сессии обрываются — попытка и AI не тратятся. Данных не меняет → @prod-safe.
// Ссылка берётся из list_candidates (invite.token) сохранённой сессией business — паролей нет.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openWithApi, Api } from '../support/api';
import { blockCallStarts, candidateRow } from './support';

const HASH = '#e94412 · #6a993d709f3da75a35e94412';
const SUCCESS = (process.env.QA_E94412_SUCCESS_CANDIDATES || 'QA-C4-2110-D2,QA-DIAG-2110').split(',').map((s) => s.trim()).filter(Boolean);
const FAILURE = process.env.QA_E94412_FAILURE_CANDIDATE || ''; // пусто — первый подходящий кандидат с technical_failure

type Row = {
  id: string;
  full_name: string;
  invite: { token: string; status: string; expires_at: string } | null;
  attempt: { id: string; status: string; attempt_type?: string } | null;
};

const TXT = {
  doneTitle: 'הסימולציה הושלמה',
  doneSent: (biz: string) => `התוצאות הועברו לצוות הגיוס של ${biz}`,
  doneNext: (biz: string) => `המשך התהליך ינוהל ישירות מול ${biz}.`,
  doneNothing: 'אין צורך לעשות דבר נוסף — הצוות יחזור אליכם.',
  failTitle: 'השיחה לא הושלמה',
  failReason: 'השיחה נקטעה בגלל תקלה טכנית',
  failNotYou: /זה לא נחשב לחובתכם\. צוות הגיוס של .+ יחזור אליכם לגבי ההמשך/,
  failSaved: 'החלק של השיחה שהוקלט עד הניתוק נשמר.',
  human: 'פנייה לגורם אנושי',
};

/** Кнопки старта на экранах кандидата — на S-17 их быть не должно (AC4). */
const START_BUTTONS = /בוא נתחיל|להתחיל|מוכן, מתחילים|לנסות שוב|להמשיך לתרגול/;

async function listCandidates(api: Api): Promise<Row[]> {
  const res = await api.rpc('list_candidates');
  expect(res.status(), await res.text()).toBe(200);
  return (await res.json()) as Row[];
}

async function businessName(api: Api, candidateId: string): Promise<string> {
  const res = await api.rpc('get_candidate_report', { p_candidate_id: candidateId, p_reason: null });
  expect(res.ok(), `get_candidate_report ${res.status()}`).toBeTruthy();
  const j = await res.json();
  const name = (Array.isArray(j) ? j[0] : j)?.business?.name as string | undefined;
  expect(name, 'имя бизнеса в отчёте').toBeTruthy();
  return name!;
}

/** Гость открывает ссылку /c/<token>; возвращает тело ответа candidate_open_link. */
async function openLink(guest: Page, token: string): Promise<string> {
  const opened = guest.waitForResponse((r) => r.url().includes('/rpc/candidate_open_link') && r.request().method() === 'POST');
  await guest.goto(`/c/${token}`);
  return (await opened).text();
}

async function expectNoStart(guest: Page) {
  await expect(guest.getByRole('button', { name: START_BUTTONS })).toHaveCount(0);
}

test.describe(`Экран завершения S-17 для кандидата (${HASH})`, () => {
  for (const name of SUCCESS) {
    test(`${name}: повторное открытие ссылки после успешной попытки — только «${TXT.doneTitle}», имя бизнеса в тексте, без балла и отчёта, старта нет (и после reload) @mobile @prod-safe ${HASH}`, async ({ asUser }) => {
      const business = await asUser('business');
      const api = await openWithApi(business, '/candidates');
      const rows = (await listCandidates(api)).filter((r) => r.full_name === name);
      expect(rows, `кандидат «${name}» (QA_E94412_SUCCESS_CANDIDATES)`).toHaveLength(1);
      const c = rows[0];
      expect(c.attempt?.status, `${name}: попытка завершена успешно`).toBe('completed');
      expect(c.invite?.token, `${name}: нет ссылки`).toBeTruthy();
      const biz = await businessName(api, c.id);

      const guest = await asUser('guest');
      const blocked = await blockCallStarts(guest);
      const body = await openLink(guest, c.invite!.token);

      // Источник: AC1 + AC5 — успешный текст, имя бизнеса вместо заполнителя.
      await expect(guest.getByText(TXT.doneTitle, { exact: true })).toBeVisible({ timeout: 30_000 });
      await expect(guest.getByText(TXT.doneSent(biz))).toBeVisible();
      await expect(guest.getByText(TXT.doneNext(biz))).toBeVisible();
      await expect(guest.getByText(TXT.doneNothing)).toBeVisible();
      const text = await guest.locator('body').innerText();
      expect(text, 'заполнитель вместо имени бизнеса').not.toMatch(/[{}]|\[\s*שם/);

      // Источник: AC2 / דרישה 2 — нет балла, отчёта, отзыва или признака качества ни на экране, ни в ответе сервера.
      expect(text).not.toMatch(/ציון|\d+\s*%|\d+\s*\/\s*100|משוב|ביצוע טוב|מתאים לתפקיד|המלצה/);
      expect(body, 'candidate_open_link отдаёт оценку/отчёт').not.toMatch(/"(score|overall_score|domains|feedback|checkpoints)"/);

      // Источник: AC4 — только экран завершения, повторить симуляцию нельзя (и после reload).
      await expectNoStart(guest);
      await guest.reload();
      await expect(guest.getByText(TXT.doneTitle, { exact: true })).toBeVisible({ timeout: 30_000 });
      await expectNoStart(guest);
      expect(blocked.start + blocked.voice, 'был запрос старта попытки/голосовой сессии').toBe(0);
    });
  }

  test(`после технического сбоя ссылка показывает «${TXT.failTitle}», «${TXT.failReason}», плашку «${TXT.failSaved}» и «${TXT.human}»; старта нет @mobile @prod-safe ${HASH}`, async ({ asUser }) => {
    const business = await asUser('business');
    const api = await openWithApi(business, '/candidates');
    const now = Date.now();
    const rows = (await listCandidates(api)).filter(
      (r) =>
        r.attempt?.status === 'technical_failure' &&
        r.attempt.attempt_type !== 'practice' &&
        !!r.invite?.token &&
        !['cancelled', 'expired'].includes(r.invite.status) &&
        Date.parse(r.invite.expires_at) > now &&
        (!FAILURE || r.full_name === FAILURE),
    );
    expect(
      rows.length,
      `нет данных: нужен кандидат с текущей официальной попыткой technical_failure и действующей ссылкой ` +
        `(QA-C6-2110-D2 сброшен 21.10). Задайте QA_E94412_FAILURE_CANDIDATE после ручного обрыва звонка.`,
    ).toBeGreaterThan(0);
    const c = rows[0];
    const biz = await businessName(api, c.id);

    const guest = await asUser('guest');
    const blocked = await blockCallStarts(guest);
    await openLink(guest, c.invite!.token);

    // Источник: AC3 / דרישה 6 / FL-38 — другой текст, команда вернётся, путь к человеку; Figma 866:10553 — плашка (реджект 13.10).
    await expect(guest.getByText(TXT.failTitle, { exact: true })).toBeVisible({ timeout: 30_000 });
    await expect(guest.getByText(TXT.failReason, { exact: true })).toBeVisible();
    await expect(guest.getByText(TXT.failNotYou)).toBeVisible();
    await expect(guest.getByText(TXT.failNotYou)).toContainText(biz);
    await expect(guest.getByText(TXT.failSaved, { exact: true })).toBeVisible();
    await expect(guest.getByRole('button', { name: TXT.human })).toBeVisible();
    await expect(guest.getByText(TXT.doneTitle, { exact: true })).toHaveCount(0);
    expect(await guest.locator('body').innerText()).not.toMatch(/ציון|\d+\s*%|משוב/);
    await expectNoStart(guest);
    expect(blocked.start + blocked.voice, 'был запрос старта попытки/голосовой сессии').toBe(0);
  });

  test(`список кандидатов: после успешного конца — «הושלמה» (${SUCCESS.join(', ')}); после сбоя — «תקלה טכנית» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const business = await asUser('business');
    const api = await openWithApi(business, '/candidates');
    const all = await listCandidates(api);

    // Источник: דרישה 5 — экран завершения продвигает статус попытки: הושלמה / תקלה טכנית.
    for (const name of SUCCESS) {
      expect(all.find((r) => r.full_name === name)?.attempt?.status, name).toBe('completed');
      const row = await candidateRow(business, name);
      await expect(row).toContainText('הושלמה');
      await expect(row).not.toContainText('תקלה טכנית');
    }

    const failed = all.find((r) => r.attempt?.status === 'technical_failure' && r.attempt.attempt_type !== 'practice' && (!FAILURE || r.full_name === FAILURE));
    expect(failed, 'нет данных: нет кандидата с текущей попыткой technical_failure (QA_E94412_FAILURE_CANDIDATE)').toBeTruthy();
    const row = await candidateRow(business, failed!.full_name);
    await expect(row).toContainText('תקלה טכנית');
  });
});
